package org.marketreview.nativeapp;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import org.json.*;
final class EvidenceReviewChecks {
 static final String FIXTURE="{\"title\":\"中文报告\",\"report\":\"全文\\n[K1]\",\"evidence\":[{\"evidenceId\":\"K1\",\"content\":\"完整证据\",\"sourceId\":1}],\"candidates\":[{\"code\":\"600000\",\"name\":\"浦发银行\",\"reason\":\"理由\",\"risk\":\"风险\",\"analysis\":\"长原分析\",\"evidenceIds\":[\"K1\"]},{\"code\":\"600000\",\"name\":\"冲突名称\"},{\"instrumentId\":\"SH:index:000001\",\"name\":\"上证指数\"}]}";
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 interface Try{void run()throws Exception;}
 static void refuses(Try work)throws Exception{boolean failed=false;try{work.run();}catch(Exception e){failed=true;}check(failed,"expected rejection");}
 static JSONArray catalogue()throws Exception{return new JSONArray().put(new JSONObject().put("id","SH:stock:600000").put("name","浦发银行")).put(new JSONObject().put("id","SH:index:000001").put("name","上证指数"));}
 static JSONObject model()throws Exception{JSONObject report=EvidenceReviewModel.decode(FIXTURE).getJSONObject(0);check(report.getJSONArray("candidates").length()==3,"no silent duplicate removal");JSONObject candidate=report.getJSONArray("candidates").getJSONObject(0);check(EvidenceReviewModel.audit(candidate,"SH:stock:600000",catalogue()).getString("identityState").equals("exact"),"exact catalogue identity");check(EvidenceReviewModel.audit(report.getJSONArray("candidates").getJSONObject(1),"SH:stock:600000",catalogue()).getString("identityState").equals("name-conflict"),"name conflict");refuses(()->EvidenceReviewModel.audit(candidate,"SZ:stock:600000",catalogue()));JSONObject changed=SourceAnalysisPacket.copy(report).put("text","changed");refuses(()->EvidenceReviewModel.validate(changed));refuses(()->EvidenceReviewModel.decode(FIXTURE+"junk"));refuses(()->EvidenceReviewModel.decode("{'title':'bad'}"));JSONObject source=new JSONObject().put("id","legacy-knowledge:1").put("text","前文完整证据后文").put("legacySource","knowledge_sources").put("legacyOriginal",new JSONObject().put("id",1)).put("sourceKind","docs");JSONObject evidence=SourceAnalysisPacket.copy(report.getJSONArray("evidence").getJSONObject(0));check(EvidenceReviewModel.citation(evidence,new JSONArray().put(source),new JSONArray()).getString("state").equals("snippet-only"),"snippet not full historical version");JSONObject ref=new JSONObject().put("kind","docs").put("id",source.getString("id")).put("snapshot",SourceAnalysisPacket.snapshot(source)).put("bodyHash",SourceAnalysisPacket.hash(source.getString("text")+'\0'));evidence.put("sourceRef",ref);check(EvidenceReviewModel.citation(evidence,new JSONArray().put(source),new JSONArray()).getString("state").equals("exact"),"frozen full source exact");source.put("text","同ID新原文");check(EvidenceReviewModel.citation(evidence,new JSONArray().put(source),new JSONArray()).getString("state").equals("missing-or-changed"),"same ID changed source");JSONObject missing=EvidenceReviewModel.citation(report.getJSONArray("evidence").getJSONObject(0),new JSONArray(),new JSONArray());check(missing.getString("state").equals("missing"),"missing citation honest");check(EvidenceReviewModel.decode("|代码|名称|理由|风险|原分析|\n|---|---|---|---|---|\n|600000|浦发银行|理由|风险|全文|").getJSONObject(0).getJSONArray("candidates").length()==1,"legacy Markdown");JSONObject inline=EvidenceReviewModel.decode("600000 浦发银行 理由：经营稳健 风险：估值 原分析：完整分析").getJSONObject(0).getJSONArray("candidates").getJSONObject(0);check(inline.getString("name").equals("浦发银行")&&inline.getString("reason").equals("经营稳健")&&inline.getString("risk").equals("估值"),"legacy inline labels parsed without swallowing name");JSONObject numeric=EvidenceReviewModel.decode("{\"candidates\":[{\"code\":600000,\"name\":\"浦发银行\",\"risks\":[\"风险一\",\"风险二\"]}]}").getJSONObject(0).getJSONArray("candidates").getJSONObject(0);check(numeric.getString("code").equals("600000")&&numeric.getString("risk").equals("风险一；风险二"),"legacy complete numeric code and risk arrays");refuses(()->EvidenceReviewModel.decode("{\"candidates\":[{\"code\":1,\"name\":\"不得补零\"}]}"));return report;}
 public static void main(String[] args)throws Exception{JSONObject report=model();if(args.length>0)Files.write(new File(args[0]).toPath(),EvidenceReviewModel.json(report).getBytes(StandardCharsets.UTF_8));System.out.println("PASS evidence review production Java model identity/nameconflict/fullreport/citations/no-silent-dedup/strict-tail/Markdown; no device/DB/network");}
 static void run(FlowInstrumentation f)throws Exception{model();File file=f.activity.getDatabasePath("evidence-review-checks-"+System.nanoTime()+".sqlite");EvidenceReviewStore store=new EvidenceReviewStore(file);JSONObject preview=store.preview(FIXTURE);check(store.list("reports",0).length()==0,"preview readonly");JSONObject stage=store.stage(preview,"");refuses(()->store.merge(preview,"stale"));store.merge(preview,stage.getString("recordRevision"));JSONObject report=store.get("reports",preview.getJSONArray("rows").getJSONObject(0).getJSONObject("record").getString("id"));check(store.get("previews","import-preview").getJSONObject("preview").length()==0,"atomic consume");JSONArray selected=new JSONArray().put(EvidenceReviewModel.audit(report.getJSONArray("candidates").getJSONObject(0),"SH:stock:600000",catalogue()));JSONObject saved=store.approve(report.getString("id"),selected,true,catalogue());JSONObject forged=SourceAnalysisPacket.copy(saved).put("candidates",new JSONArray().put(SourceAnalysisPacket.copy(selected.getJSONObject(0)).put("reason","not original")));refuses(()->EvidenceReviewModel.validate(forged));refuses(()->store.approve(report.getString("id"),selected,true,catalogue()));EvidenceReviewStore backup=new EvidenceReviewStore(f.activity.getDatabasePath("evidence-review-backup-"+System.nanoTime()+".sqlite"));backup.merge(backup.preview(new String(store.backup(),StandardCharsets.UTF_8)),"");check(backup.list("batches",0).length()==1,"full backup");f.ui(()->{try{EvidenceReviewScreen screen=new EvidenceReviewScreen(f.activity,f.activity.businessStore,file,EvidenceReviewChecks::catalogue,null,null);screen.input.setText("recoverable draft");screen.previewImport(FIXTURE);EvidenceReviewScreen recreated=new EvidenceReviewScreen(f.activity,f.activity.businessStore,file,EvidenceReviewChecks::catalogue,null,null);check(recreated.input.getText().toString().equals("recoverable draft")&&recreated.pending.getJSONArray("rows").length()==1,"recreation draft plus staged preview");recreated.setDarkTheme(true);recreated.read("完整引用");check(recreated.back()&&!recreated.back(),"internal back");}catch(Exception e){throw new RuntimeException(e);}});}
}




